(() => {const hero = document.querySelector(".hero");if (!hero) return;const slides = hero.querySelectorAll(".hero-slide");if (slides.length < 2) return;const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;const nextBtn = hero.querySelector(".hero-swipe-next");let active = 0;let animating = false;let timerId = null;const intervalMs = 4500;const transitionMs = reduceMotion ? 0: 950;const allStateClasses = ["is-active","is-next","is-prev","is-out","is-out-right"];const normalize = (index) => (index + slides.length) % slides.length;const parkSlides = () => {const prevIndex = normalize(active - 1);slides.forEach((slide,idx) => {slide.classList.remove(...allStateClasses);if (idx === active) {slide.classList.add("is-active")} else if (idx === prevIndex) {slide.classList.add("is-prev")} else {slide.classList.add("is-next")}})};const moveTo = (nextIndex,direction) => {if (animating || nextIndex === active) return;const current = slides[active];const next = slides[nextIndex];animating = true;current.classList.remove("is-active");current.classList.add(direction > 0 ? "is-out": "is-out-right");next.classList.remove("is-next","is-prev");next.classList.add("is-active");window.setTimeout(() => {active = nextIndex;parkSlides();animating = false},transitionMs)};const nextSlide = () => {moveTo(normalize(active + 1),1)};const prevSlide = () => {moveTo(normalize(active - 1),-1)};const restartTimer = () => {if (timerId) window.clearInterval(timerId);if (reduceMotion) return;timerId = window.setInterval(() => {nextSlide()},intervalMs)};parkSlides();restartTimer();if (nextBtn) {nextBtn.addEventListener("click",() => {nextSlide();restartTimer()})} let touchStartX = null;hero.addEventListener("touchstart",(event) => {if (!event.touches || event.touches.length !== 1) return;touchStartX = event.touches[0].clientX},{passive: true});hero.addEventListener("touchend",(event) => {if (touchStartX === null || !event.changedTouches || !event.changedTouches.length) return;const diffX = event.changedTouches[0].clientX - touchStartX;touchStartX = null;if (Math.abs(diffX) < 40) return;if (diffX > 0) {prevSlide()} else {nextSlide()} restartTimer()},{passive: true})})();(() => {const STORAGE_KEY = "altis_lang";const translations = {ko: {navHome: "Home",navAbout: "About",navTeams: "Teams",navTech: "Tech",navMedia: "Media",navsponsors: "sponsors",langToggle: "<span class=\"lang-option lang-kr\">KR</span> / <span class=\"lang-option lang-en\">EN</span>",heroTitle: "Our Dream<br />Toward the Cosmos",heroTagline: "LUCE IN ALTIS",heroCtaSupport: "Support for ALTIS",heroCtaMedia: "YouTube 영상 보기",heroCtaAbout: "About ALTIS",aboutKicker: "Luce in ALTIS",aboutTitle: "높은 곳에서 빛나라",aboutBody1: "높은 곳에서 빛나기 위해, ALTIS는 경상국립대학교 우주항공대학 항공우주공학부 학생들이 직접 로켓을 설계·제작·시험하는 동아리입니다. 우리는 스스로 배우고 만들며, 로켓 시스템 전반의 이해와 기술 역량을 차근히 쌓아갑니다.",aboutBody2: "그 빛을 실제로 쏘아 올리기 위해 고체 로켓 모터 설계·제작부터 추력·압력 계측, 전자부(에비오닉스)와 구조 설계, 지상 및 발사 시험까지 전 과정을 수행합니다.",coreKicker: "Core Value",coreTitle: "Design · Build · Launch",coreBody1: "모든 프로젝트는 이론 검토에 그치지 않고 실제 하드웨어 제작과 반복적인 시험 과정을 통해 검증됩니다. 설계–제작–시험의 반복 과정을 통해 발생하는 문제를 분석하고 개선하는 것이 ALTIS 프로젝트의 핵심 가치입니다.",coreBody2: "ALTIS는 단순한 동아리 활동을 넘어 대학 수준에서 수행 가능한 항공우주 공학 프로젝트의 한계를 확장하고, 학생들이 실제 엔지니어링 환경과 유사한 경험을 쌓을 수 있는 팀을 지향합니다.",techMotorBody: "이번 모터는 2 MPa의 비교적 낮은 압력을 기준으로 안전을 우선해 설계한 고체 모터입니다. 실제 제작과 시험을 염두에 두고 구조를 단순화했으며, 안정적인 점화와 추력 확보를 목표로 반복 시험에 적합한 형상으로 개발했습니다.",techAvionicsBody: "비행 데이터 계측과 점화 제어를 담당하는 에비오닉스 보드입니다. 전원 안정화, 센서 인터페이스, 릴레이 제어 모듈을 통합해 발사 시퀀스를 안정적으로 수행합니다.",techFlashBody: "현장 점화와 계측을 위한 통합 콘솔로, 시스템 상태 확인과 실시간 데이터 모니터링을 제공합니다. 안정성을 우선한 작업 흐름으로 점화 준비부터 기록 관리까지 하나의 화면에서 제어합니다.",techFlashCta: "Go to FLASH",techRecoveryBody: "비행 종료 후 안전한 회수를 위해 낙하산 사출 모듈을 설계했습니다. 분리부 하우징과 가이드 구조를 단순화해 신뢰성을 높이고, 현장 점검과 조립이 쉬운 구조로 구성했습니다.",techAirframeBody: "동체 설계는 탑재체 보호와 구조 강도를 동시에 확보하는 방향으로 설계했습니다. 내부 전자부 탑재와 분리 모듈이 안정적으로 결합되도록 구조 간섭을 최소화했습니다.",teamKicker: "Team Structure",teamTitle: "ALTIS 팀 구성",teamIntro: "추진·미션·동체·전자 팀이 유기적으로 협업하며 설계부터 시험까지의 전 과정을 수행합니다.",teamPropulsionTitle: "추진팀",teamPropulsionBody: "고체 로켓 모터 설계·제작, 추력 계측 및 추진 시스템 검증을 담당합니다.",teamMissionTitle: "미션팀",teamMissionBody: "비행 시퀀스·시험 계획 수립과 임무 운영 시나리오를 설계합니다.",teamAirframeTitle: "동체팀",teamAirframeBody: "구조 설계, 하우징 제작, 조립 공정 등 발사체 구조물을 책임집니다.",teamAvionicsTitle: "전자팀",teamAvionicsBody: "DAQ, 센서 인터페이스, 점화 제어, 통신 모듈 등 전자부 시스템을 개발합니다.",galleryKicker: "Field Log",galleryTitle: "현장 기록",galleryHint: "스와이프 →",mediaTitle: "YouTube Feature",mediaIntro: "ALTIS가 출연한 유튜브 영상을 통해 팀 활동과 프로젝트를 확인해보세요.",mediaVideo1Title: "작은 교실, 큰 우주ㅣ영남 라디오스타",mediaVideo1Body: "#영남라디오스타 #kbs #경남 #우주",mediaVideo2Title: "로켓도 직접 만드는 학과가 있다?!│우문현답 EP.1",mediaVideo2Body: "#우주항공청 #KASA #경상대 #항공우주 ",mediaWatch: "유튜브에서 보기",partnerTitle: "sponsors",partnerEmptyTitle: "아직 스폰서가 없습니다",partnerEmptyBody: "ALTIS는 여러분의 관심을 매우 환영합니다.",partnerEmptyLink: "자세히 보기",},en: {navHome: "Home",navAbout: "About",navTeams: "Teams",navTech: "Tech",navMedia: "Media",navsponsors: "sponsors",langToggle: "<span class=\"lang-option lang-kr\">KR</span> / <span class=\"lang-option lang-en\">EN</span>",heroTitle: "Our Dream<br />Toward the Cosmos",heroTagline: "LUCE IN ALTIS",heroCtaSupport: "Support for ALTIS",heroCtaMedia: "YouTube Feature",heroCtaAbout: "About ALTIS",aboutKicker: "Luce in ALTIS",aboutTitle: "Shine Higher",aboutBody1: "To shine at higher altitudes, ALTIS is a club where aerospace engineering students at Gyeongsang National University design, build, and test rockets themselves. We learn by doing, steadily building understanding and technical skill across the entire rocket system.",aboutBody2: "To launch that light into the sky, we cover the full process—from solid motor design and fabrication to thrust and pressure measurement, avionics and structural design, and ground and launch testing.",coreKicker: "Core Value",coreTitle: "Design · Build · Test",coreBody1: "Every project goes beyond theory and is validated through real hardware builds and repeated tests. Analyzing issues and improving through the design–build–test cycle is the core value of ALTIS projects.",coreBody2: "ALTIS goes beyond a typical club, expanding the boundaries of university-level aerospace projects and providing students with experience similar to real engineering environments.",techMotorBody: "This motor is a solid motor designed with safety as the priority, based on a relatively low pressure of 2 MPa. We simplified the structure for practical fabrication and testing, and developed a geometry suited for repeated tests to ensure reliable ignition and thrust.",techAvionicsBody: "This avionics board handles flight data acquisition and ignition control. It integrates power regulation, sensor interfaces, and relay control modules to execute the launch sequence reliably.",techFlashBody: "An integrated console for field ignition and measurement, providing system status checks and real-time data monitoring. With safety-first workflows, it controls everything from ignition prep to logging in a single screen.",techFlashCta: "Go to FLASH",techRecoveryBody: "We designed a parachute ejection module for safe recovery after flight. By simplifying the separation housing and guide structure, we improved reliability and made on-site inspection and assembly easier.",techAirframeBody: "The airframe is designed to protect payloads while ensuring structural strength. We minimized structural interference so internal avionics and separation modules integrate reliably.",teamKicker: "Team Structure",teamTitle: "ALTIS Team Structure",teamIntro: "Propulsion, mission, airframe, and avionics teams collaborate to cover the full process from design to testing.",teamPropulsionTitle: "Propulsion Team",teamPropulsionBody: "Responsible for solid motor design and fabrication, thrust measurement, and propulsion system verification.",teamMissionTitle: "Mission Team",teamMissionBody: "Designs flight sequences, test plans, and mission operation scenarios.",teamAirframeTitle: "Airframe Team",teamAirframeBody: "Handles structural design, housing fabrication, and assembly processes for the airframe.",teamAvionicsTitle: "avionics Team",teamAvionicsBody: "Develops avionics systems including DAQ, sensor interfaces, ignition control, and communications modules.",galleryKicker: "Field Log",galleryTitle: "Field Log",galleryHint: "Swipe →",mediaTitle: "YouTube Feature",mediaIntro: "Watch the YouTube videos featuring ALTIS and our project activities.",mediaVideo1Title: "ALTIS Feature Video 1",mediaVideo1Body: "A highlight clip of our team activity and launch preparation process.",mediaVideo2Title: "ALTIS Feature Video 2",mediaVideo2Body: "An interview-style highlight with team introduction and project scenes.",mediaWatch: "Watch on YouTube",partnerTitle: "sponsors",partnerEmptyTitle: "No sponsors yet",partnerEmptyBody: "ALTIS warmly welcomes your interest and support.",partnerEmptyLink: "Learn more",},};const textNodes = document.querySelectorAll("[data-i18n]");const htmlNodes = document.querySelectorAll("[data-i18n-html]");const normalizeLang = (lang) => (lang === "en" ? "en": "ko");const applyLang = (lang) => {const next = normalizeLang(lang);const map = translations[next] || {};document.documentElement.lang = next;textNodes.forEach((el) => {const key = el.getAttribute("data-i18n");if (map[key] !== undefined) {el.textContent = map[key]}});htmlNodes.forEach((el) => {const key = el.getAttribute("data-i18n-html");if (map[key] !== undefined) {el.innerHTML = map[key]}});const toggle = document.querySelector(".lang-toggle");if (toggle) {toggle.setAttribute("aria-pressed",String(next === "en"));const activeClass = "is-active";const krLabel = toggle.querySelector(".lang-kr");const enLabel = toggle.querySelector(".lang-en");if (krLabel) krLabel.classList.toggle(activeClass,next === "ko");if (enLabel) enLabel.classList.toggle(activeClass,next === "en")} localStorage.setItem(STORAGE_KEY,next);document.dispatchEvent(new CustomEvent("altis-lang-change",{detail: {lang: next}}))};const storedLang = localStorage.getItem(STORAGE_KEY);const initialLang = storedLang ? normalizeLang(storedLang): normalizeLang(document.documentElement.lang);applyLang(initialLang);const toggle = document.querySelector(".lang-toggle");if (toggle) {toggle.addEventListener("click",() => {const nextLang = document.documentElement.lang === "en" ? "ko": "en";applyLang(nextLang)})}})();(() => {const btn = document.querySelector(".mute-btn");if (!btn) return;const targetId = btn.getAttribute("data-target");const media = document.getElementById(targetId);if (!media) return;const labelMap = {ko: {muted: "음소거",sound: "소리 켜짐"},en: {muted: "Muted",sound: "Sound On"},};const getLang = () => (document.documentElement.lang === "en" ? "en": "ko");const syncLabel = (isMuted) => {const lang = getLang();btn.textContent = isMuted ? labelMap[lang].muted: labelMap[lang].sound};if (media.tagName === "IFRAME") {let isMuted = true;const iframe = media;const postPlayerCommand = (func,args = []) => {if (!iframe.contentWindow) return;iframe.contentWindow.postMessage(JSON.stringify({event: "command",func,args}),"*")};const applyHighQuality = () => {["hd1080","hd720","large"].forEach((quality) => {postPlayerCommand("setPlaybackQualityRange",[quality]);postPlayerCommand("setPlaybackQuality",[quality])})};const initIframePlayer = () => {postPlayerCommand("mute");applyHighQuality();postPlayerCommand("playVideo");window.setTimeout(applyHighQuality,600);window.setTimeout(applyHighQuality,1400);syncLabel(true)};iframe.addEventListener("load",initIframePlayer);window.setTimeout(initIframePlayer,260);btn.addEventListener("click",() => {isMuted = !isMuted;if (isMuted) {postPlayerCommand("mute")} else {postPlayerCommand("unMute");postPlayerCommand("setVolume",[100])} postPlayerCommand("playVideo");applyHighQuality();syncLabel(isMuted)});document.addEventListener("altis-lang-change",() => syncLabel(isMuted));syncLabel(isMuted);return} if (media instanceof HTMLMediaElement) {btn.addEventListener("click",() => {media.muted = !media.muted;syncLabel(media.muted)});document.addEventListener("altis-lang-change",() => syncLabel(media.muted));syncLabel(media.muted)}})();(() => {const nav = document.querySelector(".nav");const menuBtn = document.querySelector(".menu-toggle");if (!nav || !menuBtn) return;const closeMenu = () => {nav.classList.remove("is-open");menuBtn.setAttribute("aria-expanded","false")};menuBtn.addEventListener("click",() => {const isOpen = nav.classList.toggle("is-open");menuBtn.setAttribute("aria-expanded",String(isOpen))});nav.querySelectorAll("nav a").forEach((link) => {link.addEventListener("click",closeMenu)});const mql = window.matchMedia("(max-width: 900px)");const handleResize = () => {if (!mql.matches) closeMenu()};if (mql.addEventListener) {mql.addEventListener("change",handleResize)} else {mql.addListener(handleResize)}})();(() => {const track = document.querySelector(".tech-scroll-track");const stack = document.querySelector(".tech-stack");if (!track || !stack) return;const items = Array.from(stack.querySelectorAll(".tech-stack-item"));if (!items.length) return;let current = -1;let rafId = null;const render = (index) => {current = index;items.forEach((item,i) => {item.classList.remove("is-active","is-prev","is-next","is-before","is-after");if (i === index) {item.classList.add("is-active")} else if (i === index - 1) {item.classList.add("is-prev")} else if (i === index + 1) {item.classList.add("is-next")} else if (i < index - 1) {item.classList.add("is-before")} else {item.classList.add("is-after")}})};const updateFromScroll = () => {rafId = null;if (window.matchMedia("(max-width: 900px)").matches) {if (current !== 0) render(0);return} const rect = track.getBoundingClientRect();const maxScroll = rect.height - window.innerHeight;if (maxScroll <= 0) {if (current !== 0) render(0);return} const progress = Math.min(1,Math.max(0,-rect.top / maxScroll));const nextIndex = Math.min(items.length - 1,Math.floor(progress * items.length));if (nextIndex !== current) render(nextIndex)};const requestUpdate = () => {if (rafId !== null) return;rafId = window.requestAnimationFrame(updateFromScroll)};window.addEventListener("scroll",requestUpdate,{passive: true});window.addEventListener("resize",requestUpdate);requestUpdate()})();(() => {const items = document.querySelectorAll(".reveal-slide");if (!items.length) return;const onIntersect = (entries) => {entries.forEach((entry) => {if (entry.isIntersecting) {entry.target.classList.add("is-visible")} else {entry.target.classList.remove("is-visible")}})};const observer = new IntersectionObserver(onIntersect,{threshold: 0.18,rootMargin: "0px 0px -10% 0px",});items.forEach((item) => observer.observe(item))})();(() => {const airframeImage = document.getElementById("airframe-toggle-image");if (!airframeImage) return;const airframeVisual = airframeImage.closest(".tech-visual");if (!airframeVisual) return;let changing = false;let currentSrc = airframeImage.getAttribute("src") || "img/altis_3dimg.png";const setAirframeImage = (nextSrc,nextAlt) => {if (changing || currentSrc === nextSrc) return;changing = true;airframeImage.style.opacity = "0";window.setTimeout(() => {airframeImage.onload = () => {airframeImage.style.opacity = "1";changing = false;airframeImage.onload = null};airframeImage.src = nextSrc;airframeImage.alt = nextAlt;currentSrc = nextSrc},260)};airframeImage.addEventListener("click",() => {const is3d = currentSrc.includes("altis_3dimg.png");setAirframeImage(is3d ? "img/altis_struc.png": "img/altis_3dimg.png",is3d ? "ALTIS 동체 구조 설계 도면": "ALTIS 동체 외형 렌더링")});let rafId = null;const updateByScroll = () => {rafId = null;const rect = airframeVisual.getBoundingClientRect();const vh = window.innerHeight || document.documentElement.clientHeight || 1;const start = vh * 0.92;const end = vh * 0.38;const proximity = Math.min(1,Math.max(0,(start - rect.top) / Math.max(1,start - end)));if (proximity >= 0.8) {setAirframeImage("img/altis_struc.png","ALTIS 동체 구조 설계 도면")} else if (proximity <= 0.22) {setAirframeImage("img/altis_3dimg.png","ALTIS 동체 외형 렌더링")}};const requestUpdate = () => {if (rafId !== null) return;rafId = window.requestAnimationFrame(updateByScroll)};window.addEventListener("scroll",requestUpdate,{passive: true});window.addEventListener("resize",requestUpdate);requestUpdate()})();(() => {document.addEventListener("contextmenu",(event) => {const target = event.target;if (target instanceof HTMLElement && target.closest("img, video, canvas")) {event.preventDefault()}});document.addEventListener("dragstart",(event) => {const target = event.target;if (target instanceof HTMLElement && target.closest("img, video, canvas")) {event.preventDefault()}});document.addEventListener("keydown",(event) => {const key = event.key.toLowerCase();const isMeta = event.ctrlKey || event.metaKey;if ((isMeta && (key === "s" || key === "p" || key === "u")) || key === "printscreen") {event.preventDefault()}})})();
